import{_ as t,c as i,o as s,ak as l}from"./chunks/framework.CtX3_w5e.js";const _=JSON.parse('{"title":"distributed system","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"distributed system","hugoSource":"computer-science/distributed-system/distributed-system.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/distributed-system/2026-11-17-distributed-system.md","filePath":"computer-science/distributed-system/2026-11-17-distributed-system.md","lastUpdated":1794887319000}'),r={name:"computer-science/distributed-system/2026-11-17-distributed-system.md"};function a(d,e,u,n,o,m){return s(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="distributed-system" tabindex="-1">distributed system <a class="header-anchor" href="#distributed-system" aria-label="Permalink to “distributed system”">​</a></h1><h2 id="微服务和分布式的比较" tabindex="-1">微服务和分布式的比较 <a class="header-anchor" href="#微服务和分布式的比较" aria-label="Permalink to “微服务和分布式的比较”">​</a></h2><ul><li>微服务架构和分布式架构是现代软件系统中两种重要的设计模式</li><li><strong>分布式架构</strong><ul><li>分布式架构是指将系统组件部署在不同的物理或虚拟节点上，通过网络协作完成任务。其核心目标是解决性能、可扩展性、容错性等问题，例如通过负载均衡、数据分片等技术提升系统吞吐能力</li><li>典型场景：分布式数据库（如Cassandra）、分布式计算（如Spark）</li><li>适合需要高性能、高可用性的场景，如大规模数据处理、高并发请求</li></ul></li><li><strong>微服务架构</strong><ul><li>微服务是一种将单体应用拆分为多个小型、独立服务的架构风格，每个服务围绕特定业务功能构建，通过轻量级通信（如HTTP/REST、gRPC）交互。核心目标是提升开发效率、灵活性和可维护性，解决业务复杂度问题</li><li>典型场景：电商平台（订单、库存等独立服务）。</li><li>适合业务复杂、需快速迭代的系统，尤其是多团队协作开发时</li></ul></li><li>分布式是手段：通过物理分散提升系统能力</li><li>微服务是策略：通过逻辑拆分优化开发和维护</li><li>选择依据： <ul><li>若需解决性能瓶颈，优先考虑分布式</li><li>若需应对业务复杂性，选择微服务</li></ul></li></ul>',3)])])}const b=t(r,[["render",a]]);export{_ as __pageData,b as default};
